import csv, io, os, random, subprocess, sys, time
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN, localcontext

Q = Decimal('0.01')
ROWS = 2_000_000

def parse_dec(s):
    try:
        return Decimal(s)
    except (InvalidOperation, ValueError):
        return Decimal(repr(float(s)))

def money(total):
    q = total.quantize(Q)
    if q == 0:
        return '0.00'
    return format(q, 'f')

def expected_small(data):
    text = data.decode('utf-8')
    with localcontext() as ctx:
        ctx.prec = 200
        ctx.rounding = ROUND_HALF_EVEN
        f = io.StringIO(text, newline='')
        r = csv.reader(f)
        header = next(r, None)
        if header is None:
            return b''
        try:
            ci = header.index('cat')
            vi = header.index('val')
        except (ValueError, AttributeError):
            ci, vi = 1, 2
        need = max(ci, vi)
        sums = {}
        for row in r:
            if len(row) <= need:
                continue
            cat = row[ci]
            sums[cat] = sums.get(cat, Decimal(0)) + parse_dec(row[vi])
        out = io.StringIO(newline='')
        w = csv.writer(out, lineterminator='\n')
        for cat in sorted(sums):
            w.writerow((cat, money(sums[cat])))
        return out.getvalue().encode('utf-8')

def fmt_cents(c):
    if c == 0:
        return '0.00'
    neg = c < 0
    c = -c if neg else c
    return ('-' if neg else '') + f'{c // 100}.{c % 100:02d}'

def bench_cents(v):
    v = v.strip()
    sign = 1
    if v[:1] == b'-':
        sign = -1
        v = v[1:]
    elif v[:1] == b'+':
        v = v[1:]
    dot = v.find(b'.')
    if dot < 0:
        return sign * int(v or b'0') * 100
    whole, frac = v[:dot], v[dot + 1:]
    if len(frac) >= 2:
        c = int((whole + frac[:2]) or b'0')
        rest = frac[2:]
        if rest and rest != b'0' * len(rest):
            if rest[0] > 53 or (rest[0] == 53 and (any(x != 48 for x in rest[1:]) or (c & 1))):
                c += 1
    elif len(frac) == 1:
        c = int((whole + frac + b'0') or b'0')
    else:
        c = int((whole or b'0') + b'00')
    return sign * c

def expected_bench(path='bench.csv'):
    sums = {}
    with open(path, 'rb') as f:
        next(f, None)
        for line in f:
            line = line.rstrip(b'\r\n')
            if not line:
                continue
            parts = line.split(b',')
            if len(parts) < 3:
                continue
            cat = parts[1].decode('utf-8')
            c = bench_cents(parts[2])
            sums[cat] = sums.get(cat, 0) + c
    out = io.StringIO(newline='')
    w = csv.writer(out, lineterminator='\n')
    for cat in sorted(sums):
        w.writerow((cat, fmt_cents(sums[cat])))
    return out.getvalue().encode('utf-8')

def run(data=None, path=None):
    cmd = [sys.executable, '-B', 'csvsum.py']
    if path is None:
        p = subprocess.run(cmd, input=data, stdout=subprocess.PIPE,
                           stderr=subprocess.PIPE, timeout=12)
    else:
        with open(path, 'rb') as f:
            p = subprocess.run(cmd, stdin=f, stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, timeout=12)
    if p.returncode != 0:
        raise RuntimeError('csvsum exit %d: %s' % (
            p.returncode, p.stderr.decode('utf-8', 'replace')[:300]))
    return p.stdout

def check(name, data):
    exp = expected_small(data)
    got = run(data=data)
    if got != exp:
        raise AssertionError('%s mismatch\nexp=%r\ngot=%r' % (
            name, exp[:500], got[:500]))

def make_cases():
    cases = []
    cases.append(('basic', b'id,cat,val\n1,b,1.005\n2,a,2\n3,b,-0.005\n'))
    cases.append(('quoted', b'id,cat,val\n1,"x,y",1.23\n2,"q""z",-4.567\n3,"x,y",2\n'))
    cases.append(('reordered', b'val,cat,id\n1.005,b,1\n2,a,2\n-0.005,b,3\n'))
    cases.append(('extra_col', b'id,cat,val,extra\n1,b,1.005,x\n2,a,2,y\n'))
    cases.append(('crlf_short', b'id,cat,val\r\n1,b,2.675\r\n2,a,-0.001\r\n\r\n1,onlytwo\r\n'))
    vals = [
        '0.005', '-0.005', '2.675', '-2.675', '2.665', '-2.665',
        '1e2', '-1.2e-2', '+.5', ' 4.2 ', '0001.230', '1.', '.25',
        '-3', '+7.50', '0.004999999999999999', '0.005000000000000000',
        '0.005000000000000001', '-0.005000000000000001',
        '2.674999999999999999', '2.675000000000000001',
        '1.234567890123456789', '-1.234567890123456789',
        '123456789012345678.123456789012345678',
        '1e-20', '-1e-20', '999999.999', '-999999.999'
    ]
    cats = ['alpha', 'beta,comma', 'quote"cat', 'sp ace', 'line\nbreak',
            'c000', 'z', 'A', 'a', '', 'x']
    rng = random.Random(20240517)
    buf = io.StringIO(newline='')
    w = csv.writer(buf, lineterminator='\r\n')
    w.writerow(('id', 'cat', 'val'))
    for i in range(12000):
        if i % 5 == 0:
            v = f'{rng.randint(-9999, 9999)}.{rng.randrange(100):02d}'
        elif i % 5 == 1:
            v = f'{rng.randint(-999, 999)}.{rng.randrange(1000):03d}'
        else:
            v = rng.choice(vals)
        w.writerow((i, rng.choice(cats), v))
    data = buf.getvalue().encode('utf-8') + b'\r\n1,short\r\n\r\n'
    cases.append(('random', data))
    return cases

def main():
    try:
        if not os.path.exists('bench.csv') or not os.path.exists('csvsum.py'):
            raise RuntimeError('missing files')
        for name, data in make_cases():
            check(name, data)
        exp = expected_bench('bench.csv')
        times = []
        for _ in range(2):
            t0 = time.perf_counter()
            got = run(path='bench.csv')
            t1 = time.perf_counter()
            if got != exp:
                raise AssertionError('bench mismatch: exp=%r got=%r' % (exp[:300], got[:300]))
            times.append(t1 - t0)
        best = min(times)
        if best <= 0:
            raise RuntimeError('bad timing')
        print(f'{ROWS / best:.3f}')
    except Exception as e:
        sys.stderr.write('ASSAY FAIL: %s\n' % e)
        print('0')

main()
